import { useEffect, useMemo, useState } from 'react';
import { Bike, Calculator, Check, ChevronRight, CircleDollarSign, FileSpreadsheet, FileText, History, ImagePlus, LayoutDashboard, Menu, Plus, RefreshCw, Search, Settings, Users, X } from 'lucide-react';
import { calculateFinance } from '@/lib/finance';
import { QuoteHistory } from '@/QuoteHistory';
import { findDuplicateClient, type DuplicateMatch } from '@/lib/clientDuplicates';
import { downloadBackup, downloadCsv, inspectBackup, restorePhotos, type BackupManifest } from '@/lib/backup';
import { parseExcel, parsePdf, type ExcelPreview, type PdfPrice } from '@/lib/importers';
import { defaultCompany, defaultFinance, deletePhoto, loadData, loadPhoto, loadQuoteDraft, makeId, saveData, saveQuoteDraft, savePhoto, vehiclePrice, vehiclePriceLabel, type AppData, type Client, type CompanyInfo, type FinanceConfig, type Quote, type QuoteDraft, type Vehicle } from '@/lib/storage';

type Page = 'Inicio' | 'Catálogo' | 'Cotizador' | 'Historial de cotizaciones' | 'Clientes' | 'Importaciones' | 'Finanzas' | 'Respaldos';
const money = (value: number | undefined): string => value === undefined ? 'No disponible' : new Intl.NumberFormat('es-EC', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 }).format(value);
const normalizeKey = (value: string): string => value.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().replace(/[/_-]+/g, ' ').replace(/\s+/g, ' ').trim();
const vehicleKey = (brand: string, model: string, _year?: number): string => `${normalizeKey(brand)}|${normalizeKey(model)}`;
const initialData: AppData = { vehicles: [], clients: [], quotes: [], finance: defaultFinance, company: defaultCompany };
const emptyQuoteDraft: QuoteDraft = { mode: 'Contado', clientName: '', discount: 6 };

type PhotoPlan = { items: { file: File; previewUrl: string; vehicleId: string; matched: boolean }[] };

function usePhotoUrl(photoId?: string): string | undefined {
  const [url, setUrl] = useState<string | undefined>();
  useEffect(() => {
    if (!photoId) { setUrl(undefined); return; }
    let revoked = false;
    let created: string | undefined;
    loadPhoto(photoId).then((blob) => { if (!blob || revoked) return; created = URL.createObjectURL(blob); setUrl(created); }).catch(() => setUrl(undefined));
    return () => { revoked = true; if (created) URL.revokeObjectURL(created); };
  }, [photoId]);
  return url;
}

function VehiclePhoto({ photoId, size, className }: { photoId?: string; size: number; className?: string }) {
  const url = usePhotoUrl(photoId);
  return <div className={`flex items-center justify-center overflow-hidden bg-[#e8efeb] text-[#77a191] ${className ?? ''}`}>{url ? <img src={url} alt="" className="h-full w-full object-cover" /> : <Bike size={size} strokeWidth={1.2} />}</div>;
}

function App() {
  const [data, setData] = useState<AppData>(initialData);
  const [page, setPage] = useState<Page>('Inicio');
  const [query, setQuery] = useState('');
  const [selectedVehicle, setSelectedVehicle] = useState<Vehicle | null>(null);
  const [draft, setDraft] = useState<QuoteDraft>(emptyQuoteDraft);
  const [notice, setNotice] = useState('');
  const [menuOpen, setMenuOpen] = useState(false);
  useEffect(() => { loadData().then(setData).catch(() => setNotice('No se pudo abrir el almacenamiento local.')); loadQuoteDraft().then((stored) => { if (stored) setDraft({ ...emptyQuoteDraft, ...stored }); }).catch(() => undefined); }, []);
  const updateData = (next: AppData, message?: string) => { setData(next); saveData(next).then(() => { if (message) setNotice(message); }).catch(() => setNotice('No se pudo guardar el cambio localmente.')); };
  const updateDraft = (next: QuoteDraft) => { setDraft(next); saveQuoteDraft(next).catch(() => setNotice('No se pudo guardar el borrador de la cotización.')); };
  const navigate = (next: Page) => { setPage(next); setMenuOpen(false); setSelectedVehicle(null); };
  const quoteVehicle = (vehicle: Vehicle) => { updateDraft({ ...draft, vehicleId: vehicle.id }); setPage('Cotizador'); };
  const nav = [{ label: 'Inicio', icon: LayoutDashboard }, { label: 'Catálogo', icon: Bike }, { label: 'Cotizador', icon: Calculator }, { label: 'Historial de cotizaciones', icon: History }, { label: 'Clientes', icon: Users }, { label: 'Importaciones', icon: FileSpreadsheet }, { label: 'Finanzas', icon: CircleDollarSign }, { label: 'Respaldos', icon: RefreshCw }];
  return <div className="min-h-screen bg-[#f4f7f6] text-[#17202a]">
    <aside className={`fixed inset-y-0 left-0 z-30 w-72 bg-[#102b2b] px-5 py-6 text-white transition-transform lg:translate-x-0 ${menuOpen ? 'translate-x-0' : '-translate-x-full'}`}>
      <div className="mb-10 flex items-center gap-3 px-2"><div className="rounded-2xl bg-[#d8f276] p-3 text-[#102b2b]"><Bike size={22} /></div><div><div className="text-xl font-bold tracking-tight">JC CRM</div><div className="text-xs text-[#a5c0ba]">Gestión comercial local</div></div></div>
      <div className="space-y-1">{nav.map(({ label, icon: Icon }) => <button key={label} onClick={() => navigate(label as Page)} className={`flex w-full items-center gap-3 rounded-xl px-3 py-3 text-left text-sm font-semibold transition ${page === label ? 'bg-[#d8f276] text-[#102b2b]' : 'text-[#b8cbc7] hover:bg-white/10 hover:text-white'}`}><Icon size={18} />{label}</button>)}</div>
      <div className="absolute bottom-6 left-5 right-5 rounded-2xl border border-white/10 bg-white/5 p-4"><div className="text-xs uppercase tracking-[.18em] text-[#a5c0ba]">Perfil local</div><div className="mt-2 font-semibold">{data.company.advisorName} · {data.company.name}</div><div className="mt-1 text-xs text-[#a5c0ba]">Sincronización manual por respaldo</div></div>
    </aside>
    <main className="lg:ml-72"><header className="sticky top-0 z-20 flex items-center justify-between border-b border-[#dce7e2] bg-[#f4f7f6]/95 px-5 py-4 backdrop-blur md:px-8"><button onClick={() => setMenuOpen(!menuOpen)} className="rounded-xl p-2 hover:bg-white lg:hidden"><Menu size={22} /></button><div><div className="text-sm font-medium text-[#668078]">{data.company.name}</div><h1 className="text-xl font-bold">{page}</h1></div><div className="flex items-center gap-3"><div className="hidden rounded-full bg-[#e4f1df] px-3 py-2 text-xs font-bold text-[#39704b] sm:block"><span className="mr-2 inline-block h-2 w-2 rounded-full bg-[#4b9b62]" />Datos locales activos</div><button onClick={() => navigate('Finanzas')} className="rounded-xl border border-[#dce7e2] bg-white p-2.5 hover:border-[#89a89d]"><Settings size={18} /></button></div></header>
      <div className="p-5 md:p-8">{notice && <div className="mb-6 flex items-center justify-between rounded-xl border border-[#cde4cf] bg-[#eff9ed] px-4 py-3 text-sm text-[#39704b]"><span className="flex items-center gap-2"><Check size={16} />{notice}</span><button onClick={() => setNotice('')}><X size={16} /></button></div>}
        {page === 'Inicio' && <Dashboard data={data} navigate={navigate} />}
        {page === 'Catálogo' && <Catalog vehicles={data.vehicles} query={query} setQuery={setQuery} selected={selectedVehicle} setSelected={setSelectedVehicle} navigate={navigate} quoteVehicle={quoteVehicle} updateData={updateData} data={data} />}
        {page === 'Cotizador' && <QuoteBuilder data={data} updateData={updateData} draft={draft} updateDraft={updateDraft} navigate={navigate} />}
        {page === 'Historial de cotizaciones' && <QuoteHistory data={data} navigate={navigate} />}
        {page === 'Clientes' && <Clients data={data} updateData={updateData} />}
        {page === 'Importaciones' && <Imports data={data} updateData={updateData} />}
        {page === 'Finanzas' && <FinanceSettings data={data} updateData={updateData} />}
        {page === 'Respaldos' && <Backups data={data} updateData={updateData} />}
      </div></main>
  </div>;
}

function Dashboard({ data, navigate }: { data: AppData; navigate: (page: Page) => void }) { const cards = [{ label: 'Modelos en catálogo', value: data.vehicles.length, color: 'bg-[#e8f2e9]', icon: Bike }, { label: 'Cotizaciones', value: data.quotes.length, color: 'bg-[#fff1d8]', icon: FileText }, { label: 'Clientes', value: data.clients.length, color: 'bg-[#e4edf7]', icon: Users }, { label: 'Entrada predeterminada', value: `${data.finance.entryPercent}%`, color: 'bg-[#f3eeda]', icon: CircleDollarSign }]; return <div className="fade-in"><section className="mb-8 overflow-hidden rounded-[28px] bg-[#173c3a] p-7 text-white md:p-10"><div className="max-w-2xl"><div className="mb-4 inline-flex rounded-full bg-[#d8f276] px-3 py-1 text-xs font-bold uppercase tracking-[.18em] text-[#173c3a]">Panel comercial</div><h2 className="text-3xl font-bold leading-tight md:text-5xl">Todo tu negocio, claro y listo para conversar.</h2><p className="mt-4 max-w-xl leading-7 text-[#bed2cc]">Consulta fichas, actualiza precios, simula cuotas y conserva cada decisión comercial directamente en este dispositivo.</p><div className="mt-7 flex flex-wrap gap-3"><button onClick={() => navigate('Catálogo')} className="rounded-xl bg-[#d8f276] px-5 py-3 text-sm font-bold text-[#173c3a] hover:bg-[#e5fa9c]">Abrir catálogo <ChevronRight className="ml-1 inline" size={16} /></button><button onClick={() => navigate('Importaciones')} className="rounded-xl border border-white/20 px-5 py-3 text-sm font-bold hover:bg-white/10">Actualizar archivos</button></div></div><div className="mt-8 grid grid-cols-2 gap-3 md:absolute md:ml-[52%] md:mt-[-170px] md:w-[38%]"><div className="rounded-2xl border border-white/10 bg-white/10 p-4"><div className="text-3xl font-bold">{data.vehicles.length}</div><div className="mt-1 text-xs text-[#bed2cc]">vehículos disponibles para consultar</div></div><div className="rounded-2xl border border-white/10 bg-white/10 p-4"><div className="text-3xl font-bold">{data.quotes.length}</div><div className="mt-1 text-xs text-[#bed2cc]">cotizaciones guardadas</div></div></div></section><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4">{cards.map(({ label, value, color, icon: Icon }) => <div key={label} className="rounded-2xl border border-[#dce7e2] bg-white p-5"><div className={`mb-6 inline-flex rounded-xl p-3 ${color}`}><Icon size={20} /></div><div className="text-3xl font-bold">{value}</div><div className="mt-1 text-sm text-[#668078]">{label}</div></div>)}</div><div className="mt-8 grid gap-5 lg:grid-cols-2"><ActionCard title="Siguiente paso recomendado" text={data.vehicles.length ? 'Revisa el catálogo y crea una cotización con un precio vigente.' : 'Importa el Excel técnico para comenzar a trabajar con tus modelos.'} button={data.vehicles.length ? 'Ir al cotizador' : 'Importar catálogo'} onClick={() => navigate(data.vehicles.length ? 'Cotizador' : 'Importaciones')} /><ActionCard title="Datos protegidos" text="La información se guarda en el almacenamiento local del navegador y funciona sin internet después de cargarla." button="Configurar finanzas" onClick={() => navigate('Finanzas')} /></div></div> }
function ActionCard({ title, text, button, onClick }: { title: string; text: string; button: string; onClick: () => void }) { return <div className="rounded-2xl border border-[#dce7e2] bg-white p-6"><div className="text-lg font-bold">{title}</div><p className="mt-2 max-w-lg text-sm leading-6 text-[#668078]">{text}</p><button onClick={onClick} className="mt-5 rounded-xl bg-[#173c3a] px-4 py-3 text-sm font-bold text-white hover:bg-[#235552]">{button}</button></div>; }

function Catalog({ vehicles, query, setQuery, selected, setSelected, navigate, quoteVehicle, updateData, data }: { vehicles: Vehicle[]; query: string; setQuery: (value: string) => void; selected: Vehicle | null; setSelected: (vehicle: Vehicle | null) => void; navigate: (page: Page) => void; quoteVehicle: (vehicle: Vehicle) => void; updateData: (next: AppData, message?: string) => void; data: AppData }) {
  const [targetPrice, setTargetPrice] = useState(2500);
  const [minPrice, setMinPrice] = useState('');
  const [maxPrice, setMaxPrice] = useState('');
  const [yearFilter, setYearFilter] = useState('all');
  const [typeFilter, setTypeFilter] = useState('all');
  const [engineFilter, setEngineFilter] = useState('all');
  const years = useMemo(() => [...new Set(vehicles.map((v) => v.year).filter((y): y is number => typeof y === 'number'))].sort((a, b) => a - b), [vehicles]);
  const types = useMemo(() => [...new Set(vehicles.map((v) => v.type).filter((t): t is string => Boolean(t)))].sort(), [vehicles]);
  const engines = useMemo(() => [...new Set(vehicles.map((v) => v.engine).filter((e): e is string => Boolean(e)))].sort(), [vehicles]);
  const parsedMin = minPrice.trim() === '' ? undefined : Number(minPrice);
  const parsedMax = maxPrice.trim() === '' ? undefined : Number(maxPrice);
  const min = parsedMin !== undefined && !Number.isNaN(parsedMin) && parsedMin > 0 ? parsedMin : undefined;
  const max = parsedMax !== undefined && !Number.isNaN(parsedMax) && parsedMax > 0 ? parsedMax : undefined;
  const priceError = min !== undefined && max !== undefined && min > max ? 'El precio mínimo no puede ser mayor al máximo. Revisa los valores para aplicar el rango.' : '';
  const results = useMemo(() => {
    const q = query.toLowerCase();
    const target = targetPrice > 0 ? targetPrice : undefined;
    const filtered = vehicles.filter((vehicle) => {
      if (q && !`${vehicle.brand} ${vehicle.model} ${vehicle.type ?? ''}`.toLowerCase().includes(q)) return false;
      if (yearFilter !== 'all' && vehicle.year !== Number(yearFilter)) return false;
      if (typeFilter !== 'all' && normalizeKey(vehicle.type ?? '') !== normalizeKey(typeFilter)) return false;
      if (engineFilter !== 'all' && normalizeKey(vehicle.engine ?? '') !== normalizeKey(engineFilter)) return false;
      if (priceError) return true;
      if (min !== undefined || max !== undefined) { const price = vehiclePrice(vehicle); if (price === undefined) return false; if (min !== undefined && price < min) return false; if (max !== undefined && price > max) return false; }
      return true;
    });
    if (target === undefined) return filtered;
    return [...filtered].sort((a, b) => { const pa = vehiclePrice(a); const pb = vehiclePrice(b); if (pa === undefined && pb === undefined) return 0; if (pa === undefined) return 1; if (pb === undefined) return -1; return Math.abs(pa - target) - Math.abs(pb - target); });
  }, [vehicles, query, min, max, targetPrice, yearFilter, typeFilter, engineFilter, priceError]);
  return <div className="fade-in"><div className="mb-6 flex flex-col gap-4 md:flex-row md:items-end md:justify-between"><div><p className="text-sm text-[#668078]">Fuente central de información</p><h2 className="mt-1 text-3xl font-bold">Catálogo de vehículos</h2></div><div className="relative w-full md:w-80"><Search className="absolute left-3 top-3.5 text-[#668078]" size={18} /><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Buscar marca o modelo" className="w-full rounded-xl border border-[#dce7e2] bg-white py-3 pl-10 pr-4 outline-none focus:border-[#6b9586]" /></div></div><div className="mb-6 grid gap-3 rounded-2xl border border-[#dce7e2] bg-white p-4 sm:grid-cols-2 lg:grid-cols-6"><label className="text-xs font-semibold text-[#668078]">Precio objetivo<span className="block text-[11px] font-normal text-[#9baba2]">0 = orden original</span><input type="number" min={0} value={targetPrice} onChange={(event) => setTargetPrice(event.target.value === '' ? 0 : Number(event.target.value))} className="mt-1 w-full rounded-lg border border-[#dce7e2] p-2 text-sm" placeholder="0" /></label><label className="text-xs font-semibold text-[#668078]">Precio mín.<input type="number" min={0} value={minPrice} onChange={(event) => setMinPrice(event.target.value)} className="mt-1 w-full rounded-lg border border-[#dce7e2] p-2 text-sm" placeholder="Sin límite" /></label><label className="text-xs font-semibold text-[#668078]">Precio máx.<input type="number" min={0} value={maxPrice} onChange={(event) => setMaxPrice(event.target.value)} className="mt-1 w-full rounded-lg border border-[#dce7e2] p-2 text-sm" placeholder="Sin límite" /></label><label className="text-xs font-semibold text-[#668078]">Año<select value={yearFilter} onChange={(event) => setYearFilter(event.target.value)} className="mt-1 w-full rounded-lg border border-[#dce7e2] p-2 text-sm"><option value="all">Todos</option>{years.map((y) => <option key={y} value={String(y)}>{y}</option>)}</select></label><label className="text-xs font-semibold text-[#668078]">Tipo<select value={typeFilter} onChange={(event) => setTypeFilter(event.target.value)} className="mt-1 w-full rounded-lg border border-[#dce7e2] p-2 text-sm"><option value="all">Todos</option>{types.map((t) => <option key={t} value={t}>{t}</option>)}</select></label><label className="text-xs font-semibold text-[#668078]">Cilindraje<select value={engineFilter} onChange={(event) => setEngineFilter(event.target.value)} className="mt-1 w-full rounded-lg border border-[#dce7e2] p-2 text-sm"><option value="all">Todos</option>{engines.map((e) => <option key={e} value={e}>{e}</option>)}</select></label></div>{priceError && <div className="mb-4 rounded-xl bg-[#fff0ee] p-3 text-sm font-semibold text-[#a44335]">{priceError}</div>}{selected ? <VehicleDetail vehicle={selected} back={() => setSelected(null)} quote={() => quoteVehicle(selected)} onSave={(updated) => { updateData({ ...data, vehicles: data.vehicles.map((v) => v.id === updated.id ? updated : v) }, 'Cambios del vehículo guardados.'); setSelected(updated); }} onPhotoChange={(photoId) => { const oldPhotoId = selected.photoId; const updated = { ...selected, photoId }; updateData({ ...data, vehicles: data.vehicles.map((v) => v.id === selected.id ? updated : v) }, photoId ? 'Fotografía del vehículo actualizada.' : 'Fotografía eliminada del vehículo.'); setSelected(updated); if (oldPhotoId && oldPhotoId !== photoId) { const stillUsed = data.vehicles.some((v) => v.id !== selected.id && v.photoId === oldPhotoId); if (!stillUsed) void deletePhoto(oldPhotoId); } }} /> : results.length ? <div className="grid gap-4 md:grid-cols-2 xl:grid-cols-3">{results.map((vehicle) => <button key={vehicle.id} onClick={() => setSelected(vehicle)} className="group rounded-2xl border border-[#dce7e2] bg-white p-5 text-left transition hover:-translate-y-1 hover:border-[#9db9ad] hover:shadow-lg"><VehiclePhoto photoId={vehicle.photoId} size={68} className="mb-5 h-36 rounded-xl" /><div className="flex items-start justify-between gap-3"><div><div className="text-xs font-bold uppercase tracking-[.14em] text-[#668078]">{vehicle.brand || 'Marca pendiente'}</div><h3 className="mt-1 text-lg font-bold">{vehicle.model || 'Modelo pendiente'}</h3></div><span className="rounded-full bg-[#edf6e9] px-2 py-1 text-[11px] font-bold text-[#39704b]">{vehicle.availability}</span></div><div className="mt-5 flex items-end justify-between"><div><div className="text-xs text-[#668078]">Precio vigente</div><div className="mt-1 text-xl font-bold text-[#173c3a]">{vehiclePriceLabel(vehicle)}</div></div><ChevronRight className="text-[#668078] transition group-hover:translate-x-1" /></div></button>)}</div> : <EmptyState title="Aún no hay vehículos" text="Importa el catálogo técnico para consultar modelos, fichas y precios." button="Ir a importaciones" onClick={() => navigate('Importaciones')} />}</div> }
function VehicleDetail({ vehicle, back, quote, onSave, onPhotoChange }: { vehicle: Vehicle; back: () => void; quote: () => void; onSave: (vehicle: Vehicle) => void; onPhotoChange: (photoId: string | undefined) => void }) { const [editing, setEditing] = useState(false); const [draft, setDraft] = useState(vehicle); useEffect(() => setDraft(vehicle), [vehicle]); const fields = [['Tipo', vehicle.type], ['Año', vehicle.year?.toString()], ['Motor / cilindraje', vehicle.engine], ['Velocidad máxima', vehicle.maxSpeed], ['Capacidad de tanque', vehicle.tank], ['Frenos', vehicle.brakes], ['Llantas', vehicle.tires], ['Suspensiones', vehicle.suspension], ['Luces', vehicle.lights], ['Tablero', vehicle.dashboard]]; const save = () => { const next = { ...draft, price: draft.salePrice ?? draft.officialPrice ?? draft.price, priceManualAdjust: draft.salePrice !== undefined && draft.salePrice !== (draft.officialPrice ?? vehicle.officialPrice) }; onSave(next); setEditing(false); }; const onPhotoSelect = async (file?: File | null) => { if (!file) return; const id = makeId('PHO'); try { await savePhoto(id, file); onPhotoChange(id); } catch { /* noop */ } }; const onPhotoRemove = () => onPhotoChange(undefined); return <div className="rounded-2xl border border-[#dce7e2] bg-white p-6"><button onClick={back} className="mb-6 text-sm font-bold text-[#39704b]">← Volver al catálogo</button><div className="grid gap-8 lg:grid-cols-[280px_1fr]"><div><VehiclePhoto photoId={vehicle.photoId} size={100} className="h-64 rounded-2xl" /><div className="mt-3 flex gap-2"><label className="flex-1 cursor-pointer rounded-xl border border-[#dce7e2] px-3 py-2 text-center text-xs font-bold hover:bg-[#f4f7f6]">{vehicle.photoId ? 'Cambiar foto' : 'Agregar foto'}<input type="file" accept="image/*" className="hidden" onChange={(event) => void onPhotoSelect(event.target.files?.[0])} /></label>{vehicle.photoId && <button onClick={onPhotoRemove} className="rounded-xl border border-[#dce7e2] px-3 py-2 text-xs font-bold text-[#a44335] hover:bg-[#fff0ee]">Quitar</button>}</div><button onClick={quote} className="mt-4 w-full rounded-xl bg-[#173c3a] px-4 py-3 font-bold text-white">Cotizar este modelo</button></div><div><div className="flex items-start justify-between gap-3"><div><div className="text-sm font-bold uppercase tracking-[.14em] text-[#668078]">{vehicle.brand}</div><h2 className="mt-1 text-3xl font-bold">{vehicle.model}</h2><div className="mt-3 text-2xl font-bold text-[#39704b]">{vehiclePriceLabel(vehicle)}</div>{vehicle.officialPriceText && <div className="mt-1 text-xs text-[#668078]">Texto del PDF: {vehicle.officialPriceText}</div>}</div><button onClick={() => setEditing(!editing)} className="rounded-xl border border-[#dce7e2] px-4 py-2 text-sm font-bold hover:bg-[#f4f7f6]">{editing ? 'Cancelar' : 'Editar precios'}</button></div>{editing ? <div className="mt-6 space-y-4"><div className="rounded-xl bg-[#f4f7f6] p-4"><div className="text-sm font-semibold">Precio oficial del PDF</div><input type="number" value={draft.officialPrice ?? ''} onChange={(event) => setDraft({ ...draft, officialPrice: event.target.value === '' ? undefined : Number(event.target.value) })} className="field mt-2" placeholder="Precio del documento" /><div className="mt-2"><div className="text-xs text-[#668078]">Texto original del precio</div><input value={draft.officialPriceText ?? ''} onChange={(event) => setDraft({ ...draft, officialPriceText: event.target.value })} className="field mt-1" placeholder="Ej: 699 más IVA" /></div><div className="mt-2"><div className="text-xs text-[#668078]">Condición del precio</div><input value={draft.priceCondition ?? ''} onChange={(event) => setDraft({ ...draft, priceCondition: event.target.value })} className="field mt-1" placeholder="Ej: más IVA" /></div></div><div className="rounded-xl bg-[#fff8e9] p-4"><div className="text-sm font-semibold text-[#80662c]">Precio de venta vigente (CRM)</div><input type="number" value={draft.salePrice ?? ''} onChange={(event) => setDraft({ ...draft, salePrice: event.target.value === '' ? undefined : Number(event.target.value) })} className="field mt-2" placeholder="Dejar vacío para usar el oficial" /><div className="mt-2 text-xs text-[#80662c]">Si lo modificas, se marcará como ajuste manual y no se sobrescribirá con futuras importaciones del PDF.</div></div><div className="rounded-xl bg-[#f4f7f6] p-4"><div className="text-sm font-semibold">Observaciones comerciales</div><textarea value={draft.commercialNotes ?? ''} onChange={(event) => setDraft({ ...draft, commercialNotes: event.target.value })} className="field mt-2 min-h-20" placeholder="Notas internas (no se envían al cliente)" /></div><button onClick={save} className="w-full rounded-xl bg-[#d8f276] px-4 py-3 font-bold text-[#173c3a]">Guardar cambios</button></div> : <div className="mt-8 grid gap-4 sm:grid-cols-2">{fields.map(([label, value]) => <div key={label} className="border-b border-[#edf1ef] pb-3"><div className="text-xs text-[#668078]">{label}</div><div className="mt-1 font-semibold">{value || 'No disponible'}</div></div>)}{vehicle.commercialNotes && <div className="border-b border-[#edf1ef] pb-3 sm:col-span-2"><div className="text-xs text-[#668078]">Observaciones comerciales</div><div className="mt-1 text-sm">{vehicle.commercialNotes}</div></div>}</div>}</div></div></div>; }

const clampValue = (value: number, min: number, max: number) => Math.min(Math.max(value, min), max);
const roundMoney = (value: number) => Math.round(value * 100) / 100;

function QuoteBuilder({ data, updateData, draft, updateDraft, navigate }: { data: AppData; updateData: (next: AppData, message?: string) => void; draft: QuoteDraft; updateDraft: (next: QuoteDraft) => void; navigate: (page: Page) => void }) { const setDraftField = <K extends keyof QuoteDraft>(key: K, value: QuoteDraft[K]) => updateDraft({ ...draft, [key]: value }); const { mode, clientName, discount } = draft; const entryMode = draft.entryMode ?? 'pct'; const setMode = (value: QuoteDraft['mode']) => setDraftField('mode', value); const setClientName = (value: string) => setDraftField('clientName', value); const setDiscount = (value: number) => setDraftField('discount', value); const term = draft.term !== undefined && data.finance.enabledTerms.includes(draft.term) ? draft.term : data.finance.term; const setTerm = (value: number) => setDraftField('term', value); const vehicle = data.vehicles.find((item) => item.id === draft.vehicleId); const basePrice = vehicle ? vehiclePrice(vehicle) : undefined; const defaultEntryPercent = clampValue(draft.entryPercent ?? data.finance.entryPercent, 0, 100); const entryAmount = basePrice === undefined ? 0 : roundMoney(entryMode === 'usd' ? clampValue(draft.entryAmount ?? basePrice * defaultEntryPercent / 100, 0, basePrice) : basePrice * defaultEntryPercent / 100); const entryPercent = basePrice && entryMode === 'usd' ? (entryAmount / basePrice) * 100 : defaultEntryPercent; const setEntryMode = (value: 'pct' | 'usd') => updateDraft({ ...draft, entryMode: value, entryAmount, entryPercent }); const setEntryAmount = (value: number) => setDraftField('entryAmount', roundMoney(clampValue(value, 0, basePrice ?? 0))); const setEntryPercent = (value: number) => setDraftField('entryPercent', clampValue(value, 0, 100)); const result = basePrice ? calculateFinance(basePrice, data.finance, entryPercent, term) : null; const finalCash = basePrice ? basePrice * (1 - discount / 100) : 0; const saveQuote = () => { if (!vehicle || basePrice === undefined) return; const quote: Quote = { id: makeId('COT'), vehicleId: vehicle.id, vehicleName: `${vehicle.brand} ${vehicle.model}`, price: basePrice, mode, clientName, total: mode === 'Contado' ? finalCash : result?.totalPaid ?? 0, createdAt: new Date().toISOString(), finance: mode === 'Financiado' ? { ...data.finance, entryPercent, term } : undefined, entryAmount: mode === 'Financiado' ? entryAmount : undefined, discountPercent: mode === 'Contado' ? discount : undefined, discountAmount: mode === 'Contado' ? roundMoney(basePrice * discount / 100) : undefined, calculation: mode === 'Financiado' ? result ?? undefined : undefined }; updateData({ ...data, quotes: [quote, ...data.quotes] }, 'Cotización guardada con los valores de esta versión.'); }; return <div className="fade-in"><div className="mb-6"><p className="text-sm text-[#668078]">Precios y parámetros guardados</p><h2 className="mt-1 text-3xl font-bold">Cotizador comercial</h2></div><div className="grid gap-5 xl:grid-cols-[1fr_360px]"><div className="rounded-2xl border border-[#dce7e2] bg-white p-6"><div className="grid gap-4 md:grid-cols-2"><div className="text-sm font-semibold">Vehículo<div className="mt-2 rounded-xl border border-[#dce7e2] bg-[#f4f7f6] p-3 font-normal">{vehicle ? `${vehicle.brand} ${vehicle.model} · ${vehiclePriceLabel(vehicle)}` : 'Ninguno seleccionado'}</div></div><label className="text-sm font-semibold">Cliente (opcional)<input value={clientName} onChange={(event) => setClientName(event.target.value)} placeholder="Nombre del cliente" className="mt-2 w-full rounded-xl border border-[#dce7e2] p-3" /></label></div><div className="mt-7 flex gap-2 rounded-xl bg-[#f4f7f6] p-1"><button onClick={() => setMode('Contado')} className={`flex-1 rounded-lg px-4 py-3 text-sm font-bold ${mode === 'Contado' ? 'bg-white shadow-sm' : 'text-[#668078]'}`}>Contado</button><button onClick={() => setMode('Financiado')} className={`flex-1 rounded-lg px-4 py-3 text-sm font-bold ${mode === 'Financiado' ? 'bg-white shadow-sm' : 'text-[#668078]'}`}>Financiado</button></div>{vehicle ? <div className="mt-7 rounded-2xl bg-[#173c3a] p-6 text-white"><div className="text-sm text-[#bed2cc]">{vehicle.brand} · Año {vehicle.year ?? 'N/D'}</div><div className="text-2xl font-bold">{vehicle.model}</div><div className="mt-5 grid gap-4 sm:grid-cols-2"><div><div className="text-xs text-[#bed2cc]">Precio de catálogo</div><div className="text-xl font-bold">{money(basePrice)}</div>{vehicle.priceCondition && <div className="mt-1 text-xs text-[#d8f276]">Condición: {vehicle.priceCondition}</div>}{vehicle.priceManualAdjust && <div className="mt-1 text-xs text-[#bed2cc]">Precio de venta con ajuste manual</div>}</div>{mode === 'Contado' ? <label className="text-sm">Descuento autorizado (%)<input type="number" min="0" value={discount} onChange={(event) => setDiscount(Number(event.target.value))} className="mt-1 w-full rounded-lg border-0 bg-white/10 p-2 text-white outline-none" /></label> : <><div className="text-sm">Entrada<div className="mt-1 flex gap-1 rounded-lg bg-white/10 p-1 text-xs font-bold">{(['pct', 'usd'] as const).map((option) => <button key={option} onClick={() => setEntryMode(option)} className={`flex-1 rounded-md px-2 py-1.5 ${entryMode === option ? 'bg-white text-[#173c3a]' : 'text-white'}`}>{option === 'usd' ? 'Dólares ($)' : 'Porcentaje (%)'}</button>)}</div></div><label className="text-sm">{entryMode === 'usd' ? 'Monto de entrada ($)' : 'Entrada (%)'}<input type="number" min="0" max={entryMode === 'usd' ? basePrice : 100} step="0.01" value={entryMode === 'usd' ? entryAmount : entryPercent} onChange={(event) => (entryMode === 'usd' ? setEntryAmount(Number(event.target.value)) : setEntryPercent(Number(event.target.value)))} className="mt-1 w-full rounded-lg border-0 bg-white/10 p-2 text-white outline-none" /></label><div className="text-xs text-[#bed2cc]">Equivale a {money(entryAmount)} · {entryPercent.toFixed(2)}%</div><label className="text-sm">Plazo (meses)<select value={term} onChange={(event) => setTerm(Number(event.target.value))} className="mt-1 w-full rounded-lg border-0 bg-white/10 p-2 text-white outline-none">{data.finance.enabledTerms.map((option) => <option key={option} value={option} className="text-[#17202a]">{option} meses</option>)}</select></label></>}</div>{vehicle.priceCondition && <div className="mt-4 rounded-lg bg-[#1f4a48] p-3 text-xs text-[#d8f276]"><b>Atención:</b> este precio está sujeto a «{vehicle.priceCondition}». El monto mostrado no incluye el impuesto o condición adicional; confírmalo con el cliente antes de cerrar.</div>}</div> : <div className="mt-7 rounded-xl border border-dashed border-[#b8cbc7] p-8 text-center text-sm text-[#668078]"><p>Elige un modelo desde el catálogo para ver el cálculo.</p><button onClick={() => navigate('Catálogo')} className="mt-4 rounded-xl bg-[#173c3a] px-4 py-3 font-bold text-white">Ir al catálogo</button></div>}</div><div className="rounded-2xl border border-[#dce7e2] bg-white p-6"><div className="flex items-center justify-between"><h3 className="text-lg font-bold">Resumen</h3><span className="rounded-full bg-[#fff1d8] px-3 py-1 text-xs font-bold text-[#9b6d22]">{mode}</span></div>{vehicle && basePrice !== undefined && <div className="mt-6 space-y-4 text-sm"><Row label="Precio base" value={money(basePrice)} />{vehicle.priceCondition && <Row label="Condición" value={vehicle.priceCondition} />}{mode === 'Contado' ? <><Row label={`Descuento (${discount}%)`} value={`− ${money(basePrice * discount / 100)}`} /><Row label="Precio final" value={money(finalCash)} strong /></> : result && <><Row label={`Entrada (${entryPercent.toFixed(2)}%)`} value={money(result.entry)} /><Row label="Monto financiado" value={money(result.principal)} /><Row label="Tasa aplicada" value={`${data.finance.annualRate}% ${data.finance.ratePeriod.toLowerCase()}`} /><Row label={`Cuota estimada · ${term} meses`} value={money(result.payment)} strong /><Row label="Total pagado" value={money(result.totalPaid)} strong /><p className="rounded-xl bg-[#fff8e9] p-3 text-xs leading-5 text-[#80662c]">{result.warnings[0]}</p></>}</div>}<button onClick={saveQuote} disabled={!vehicle || basePrice === undefined} className="mt-8 w-full rounded-xl bg-[#d8f276] px-4 py-3 font-bold text-[#173c3a] disabled:cursor-not-allowed disabled:opacity-50">Guardar cotización</button></div></div></div> }
function Row({ label, value, strong }: { label: string; value: string; strong?: boolean }) { return <div className={`flex justify-between gap-4 border-b border-[#edf1ef] pb-3 ${strong ? 'text-base font-bold text-[#173c3a]' : ''}`}><span className="text-[#668078]">{label}</span><span>{value}</span></div>; }

function Clients({ data, updateData }: { data: AppData; updateData: (next: AppData, message?: string) => void }) { const [name, setName] = useState(''); const [phone, setPhone] = useState(''); const [duplicate, setDuplicate] = useState<DuplicateMatch | null>(null); const [highlightId, setHighlightId] = useState<string | null>(null); const createClient = () => { const client: Client = { id: makeId('CLI'), name, phone, city: '', status: 'Calificación', notes: '', createdAt: new Date().toISOString() }; updateData({ ...data, clients: [client, ...data.clients] }, 'Cliente guardado en el CRM local.'); setName(''); setPhone(''); setDuplicate(null); }; const add = () => { if (!name.trim()) return; const match = findDuplicateClient(data.clients, name, phone); if (match) { setDuplicate(match); return; } createClient(); }; const reviewExisting = (id: string) => { setName(''); setPhone(''); setDuplicate(null); setHighlightId(id); }; const remove = (id: string) => { const client = data.clients.find((item) => item.id === id); if (!client) return; if (!window.confirm(`¿Eliminar a ${client.name} del registro de clientes?`)) return; updateData({ ...data, clients: data.clients.filter((item) => item.id !== id) }, 'Cliente eliminado del CRM local.'); }; return <div className="fade-in"><div className="mb-6"><p className="text-sm text-[#668078]">Prospectos y clientes</p><h2 className="mt-1 text-3xl font-bold">CRM comercial</h2></div><div className="grid gap-5 lg:grid-cols-[340px_1fr]"><div className="rounded-2xl border border-[#dce7e2] bg-white p-6"><h3 className="text-lg font-bold">Nuevo prospecto</h3><div className="mt-5 space-y-3"><input value={name} onChange={(event) => { setName(event.target.value); setDuplicate(null); }} placeholder="Nombres y apellidos" className="w-full rounded-xl border border-[#dce7e2] p-3" /><input value={phone} onChange={(event) => { setPhone(event.target.value); setDuplicate(null); }} placeholder="Celular" className="w-full rounded-xl border border-[#dce7e2] p-3" />{duplicate && <div className="rounded-xl border border-[#f0d8b0] bg-[#fff8e9] p-4 text-sm text-[#80662c]"><div className="font-bold">Posible cliente repetido</div><p className="mt-1">{duplicate.reason === 'phone' ? 'Ya existe un cliente con este mismo celular:' : 'Ya existe un cliente con un nombre igual:'}</p><div className="mt-2 font-semibold text-[#173c3a]">{duplicate.client.name} · {duplicate.client.phone || 'Sin celular'}</div><div className="mt-3 flex flex-col gap-2"><button onClick={() => reviewExisting(duplicate.client.id)} className="rounded-xl border border-[#dce7e2] bg-white px-4 py-2 font-bold text-[#173c3a]">Cancelar y revisar el cliente existente</button><button onClick={createClient} className="rounded-xl bg-[#173c3a] px-4 py-2 font-bold text-white">Es otra persona, crear registro nuevo</button></div></div>}<button onClick={add} className="w-full rounded-xl bg-[#173c3a] px-4 py-3 font-bold text-white"><Plus className="mr-2 inline" size={16} />Guardar prospecto</button></div></div><div className="rounded-2xl border border-[#dce7e2] bg-white p-6"><div className="mb-5 flex items-center justify-between"><h3 className="text-lg font-bold">Registro de clientes</h3><span className="text-sm text-[#668078]">{data.clients.length} registros</span></div>{data.clients.length ? <div className="space-y-3">{data.clients.map((client) => <div key={client.id} className={`flex items-center justify-between rounded-xl bg-[#f4f7f6] p-4 ${highlightId === client.id ? 'ring-2 ring-[#173c3a]' : ''}`}><div><div className="font-bold">{client.name}</div><div className="mt-1 text-sm text-[#668078]">{client.phone || 'Sin celular'} · {client.status}</div></div><div className="flex items-center gap-2"><ChevronRight size={18} className="text-[#668078]" /><button onClick={() => remove(client.id)} aria-label={`Eliminar ${client.name}`} className="rounded-lg p-2 text-[#a44335] hover:bg-[#fff0ee]"><X size={16} /></button></div></div>)}</div> : <EmptyState title="Sin clientes todavía" text="Registra un prospecto desde aquí y completa sus datos progresivamente." />}</div></div></div> }

function Imports({ data, updateData }: { data: AppData; updateData: (next: AppData, message?: string) => void }) { const [excel, setExcel] = useState<ExcelPreview | null>(null); const [pdf, setPdf] = useState<{ pages: number; rows: PdfPrice[]; conditions: string[]; scanned?: boolean } | null>(null); const [pdfPlan, setPdfPlan] = useState<{ added: { row: PdfPrice }[]; updated: { vehicle: Vehicle; row: PdfPrice; previous: number | undefined }[]; unchanged: Vehicle[]; review: { vehicle?: Vehicle; row: PdfPrice }[]; missing: Vehicle[]; manual: { vehicle: Vehicle; row: PdfPrice }[] } | null>(null); const [busy, setBusy] = useState(''); const [photoPlan, setPhotoPlan] = useState<PhotoPlan | null>(null); const importExcel = async (file: File) => { setBusy('Leyendo Excel...'); try { const preview = await parseExcel(file); setExcel(preview); } catch { setExcel({ sheet: '', headerRow: 0, headers: [], recognized: [], records: [], unknownColumns: [], errors: ['No se pudo leer el Excel. Verifica que sea un archivo válido.'] }); } finally { setBusy(''); } }; const applyExcel = () => { if (!excel?.records.length) return; const merged = [...data.vehicles]; let added = 0; excel.records.forEach((incoming) => { const existing = merged.find((item) => vehicleKey(item.brand, item.model, item.year) === vehicleKey(incoming.brand, incoming.model, incoming.year)); if (existing) Object.assign(existing, { ...incoming, id: existing.id, price: existing.price, priceText: existing.priceText, priceSource: existing.priceSource }); else { merged.push({ ...incoming, id: makeId('VEH') }); added += 1; } }); updateData({ ...data, vehicles: merged }, `Catálogo actualizado: ${added} modelos nuevos y ${excel.records.length - added} revisados.`); setExcel(null); }; const importPdf = async (file: File) => { setBusy('Extrayendo precios del PDF...'); setPdf(null); setPdfPlan(null); try { const result = await parsePdf(file); if (result.scanned) { setPdf({ pages: result.pages, rows: [], conditions: [], scanned: true }); return; } setPdf(result); try { const byKey = new Map<string, Vehicle>(); data.vehicles.forEach((v) => byKey.set(vehicleKey(v.brand, v.model, v.year), v)); const added: { row: PdfPrice }[] = []; const updated: { vehicle: Vehicle; row: PdfPrice; previous: number | undefined }[] = []; const unchanged: Vehicle[] = []; const review: { vehicle?: Vehicle; row: PdfPrice }[] = []; const manual: { vehicle: Vehicle; row: PdfPrice }[] = []; const seen = new Set<string>(); result.rows.forEach((row) => { const key = vehicleKey(row.brand, row.model, row.year); const existing = byKey.get(key); seen.add(key); if (!existing) { added.push({ row }); return; } if (row.price === undefined) { review.push({ vehicle: existing, row }); return; } if (existing.priceManualAdjust && (existing.salePrice ?? existing.officialPrice ?? existing.price) !== row.price) { manual.push({ vehicle: existing, row }); return; } const currentOfficial = existing.officialPrice ?? existing.price; if (currentOfficial === row.price) { unchanged.push(existing); } else { updated.push({ vehicle: existing, row, previous: currentOfficial }); } }); const missing = data.vehicles.filter((v) => !seen.has(vehicleKey(v.brand, v.model, v.year))); setPdfPlan({ added, updated, unchanged, review, missing, manual }); } catch (planErr) { console.error("Error al construir plan de importacion:", planErr); setPdf({ pages: result.pages, rows: [], conditions: ["Error al preparar la vista previa: " + (planErr instanceof Error ? planErr.message : "desconocido") + ". Revisa la consola del navegador (F12)."], scanned: false }); } } catch (err) { setPdf({ pages: 0, rows: [], conditions: ['No se pudo procesar el PDF. Verifica que sea un archivo válido y no esté dañado.'] }); } finally { setBusy(''); } }; const applyPdf = () => { if (!pdf || !pdfPlan) return; const byKey = new Map<string, Vehicle>(); const next = data.vehicles.map((v) => { const copy = { ...v }; byKey.set(vehicleKey(copy.brand, copy.model, copy.year), copy); return copy; }); pdfPlan.added.forEach(({ row }) => { if (!byKey.has(vehicleKey(row.brand, row.model, row.year))) { const id = makeId('VEH'); next.push({ id, brand: row.brand, model: row.model, year: row.year, officialPrice: row.price, officialPriceText: row.priceText, priceCondition: row.priceCondition, priceSource: 'SAMADI247.22.pdf', priceUpdatedAt: new Date().toISOString(), availability: 'Pendiente', price: row.price }); byKey.set(vehicleKey(row.brand, row.model, row.year), next[next.length - 1]); } }); pdfPlan.updated.forEach(({ vehicle, row }) => { const target = byKey.get(vehicleKey(vehicle.brand, vehicle.model, vehicle.year)); if (target) { target.officialPrice = row.price; target.officialPriceText = row.priceText; target.priceCondition = row.priceCondition; target.priceSource = 'SAMADI247.22.pdf'; target.priceUpdatedAt = new Date().toISOString(); if (row.year) target.year = row.year; if (!target.salePrice && !target.priceManualAdjust) target.price = row.price; } }); pdfPlan.review.forEach(({ vehicle, row }) => { if (!vehicle) return; const target = byKey.get(vehicleKey(vehicle.brand, vehicle.model, vehicle.year)); if (target) { target.officialPriceText = row.priceText; target.priceCondition = row.priceCondition; target.priceSource = 'SAMADI247.22.pdf'; target.priceUpdatedAt = new Date().toISOString(); } }); const merged = new Map<string, Vehicle>(); for (const v of next) { const k = vehicleKey(v.brand, v.model, v.year); const prev = merged.get(k); if (!prev) { merged.set(k, v); } else { merged.set(k, { ...prev, ...v, id: v.officialPrice ? v.id : prev.id, type: prev.type || v.type, engine: prev.engine || v.engine, maxSpeed: prev.maxSpeed || v.maxSpeed, tank: prev.tank || v.tank, lights: prev.lights || v.lights, valves: prev.valves || v.valves, dashboard: prev.dashboard || v.dashboard, brakes: prev.brakes || v.brakes, tires: prev.tires || v.tires, suspension: prev.suspension || v.suspension, notes: prev.notes || v.notes, raw: prev.raw || v.raw, availability: prev.availability, year: prev.year ?? v.year, officialPrice: prev.officialPrice ?? v.officialPrice, officialPriceText: prev.officialPriceText ?? v.officialPriceText, priceCondition: prev.priceCondition ?? v.priceCondition, priceSource: prev.priceSource ?? v.priceSource, priceUpdatedAt: prev.priceUpdatedAt ?? v.priceUpdatedAt, salePrice: prev.salePrice ?? v.salePrice, priceManualAdjust: prev.priceManualAdjust ?? v.priceManualAdjust, commercialNotes: prev.commercialNotes ?? v.commercialNotes, price: prev.price ?? v.price, priceText: prev.priceText ?? v.priceText }); } } const deduped = [...merged.values()]; const totalChanged = pdfPlan.added.length + pdfPlan.updated.length; updateData({ ...data, vehicles: deduped }, `Importación confirmada: ${pdfPlan.added.length} modelos nuevos, ${pdfPlan.updated.length} precios actualizados, ${pdfPlan.review.length} en revisión. ${pdfPlan.manual.length} ajustes manuales conservados.`); setPdf(null); setPdfPlan(null); }; const resolveManual = (vehicle: Vehicle, row: PdfPrice, keepManual: boolean) => { if (!pdfPlan) return; const nextManual = pdfPlan.manual.map((entry) => entry.vehicle.id === vehicle.id ? { vehicle: { ...vehicle, salePrice: keepManual ? vehicle.salePrice : row.price, priceManualAdjust: keepManual, officialPrice: row.price, officialPriceText: row.priceText, priceCondition: row.priceCondition, priceSource: 'SAMADI247.22.pdf', priceUpdatedAt: new Date().toISOString(), price: keepManual ? vehicle.price : row.price }, row } : entry); setPdfPlan({ ...pdfPlan, manual: nextManual, updated: keepManual ? pdfPlan.updated : [...pdfPlan.updated, { vehicle, row, previous: vehicle.officialPrice ?? vehicle.price }] }); }; const importPhotos = (files: FileList) => { const items = Array.from(files).filter((f) => f.type.startsWith('image/')).map((file) => { const normalizedFile = normalizeKey(file.name.replace(/\.[^.]+$/, '')); const matches = data.vehicles.filter((v) => { const key = `${normalizeKey(v.brand)} ${normalizeKey(v.model)}`.trim(); if (key.length < 2) return false; const brand = normalizeKey(v.brand); const model = normalizeKey(v.model); if (brand.length < 2 || model.length < 2) return false; return normalizedFile.includes(brand) && normalizedFile.includes(model); }); const matched = matches.length === 1; return { file, previewUrl: URL.createObjectURL(file), vehicleId: matched ? matches[0].id : '', matched }; }); setPhotoPlan({ items }); };
  const setPhotoVehicle = (index: number, vehicleId: string) => { if (!photoPlan) return; setPhotoPlan({ items: photoPlan.items.map((item, i) => i === index ? { ...item, vehicleId } : item) }); };
  const cancelPhotos = () => { if (photoPlan) photoPlan.items.forEach((item) => URL.revokeObjectURL(item.previewUrl)); setPhotoPlan(null); };
  const applyPhotos = async () => { if (!photoPlan) return; setBusy('Guardando fotografías...'); const next = data.vehicles.map((v) => ({ ...v })); let saved = 0; try { for (const item of photoPlan.items) { if (!item.vehicleId) continue; const vehicle = next.find((v) => v.id === item.vehicleId); if (!vehicle) continue; const oldPhotoId = vehicle.photoId; const id = makeId('PHO'); await savePhoto(id, item.file); vehicle.photoId = id; saved += 1; if (oldPhotoId) { const stillUsed = next.some((v) => v.id !== vehicle.id && v.photoId === oldPhotoId); if (!stillUsed) void deletePhoto(oldPhotoId); } } updateData({ ...data, vehicles: next }, `Fotografías importadas: ${saved} vinculadas, ${photoPlan.items.filter((i) => !i.vehicleId).length} sin asignar.`); photoPlan.items.forEach((item) => URL.revokeObjectURL(item.previewUrl)); setPhotoPlan(null); } finally { setBusy(''); } };
  return <div className="fade-in"><div className="mb-6"><p className="text-sm text-[#668078]">Procesamiento verificable</p><h2 className="mt-1 text-3xl font-bold">Importaciones</h2></div>{busy && <div className="mb-5 rounded-xl bg-[#e8f2e9] px-4 py-3 text-sm font-semibold text-[#39704b]"><RefreshCw className="mr-2 inline animate-spin" size={16} />{busy}</div>}<div className="grid gap-5 lg:grid-cols-2"><ImportCard icon={FileSpreadsheet} title="Excel técnico" text="Reconoce MARCA y MODELO por separado, detecta encabezados y conserva campos extra." accept=".xlsx,.xls" onChange={(file) => importExcel(file)} /><ImportCard icon={FileText} title="PDF de precios" text="Extrae páginas, modelos, años y precios promocionales para revisar antes de confirmar." accept=".pdf" onChange={(file) => importPdf(file)} /><label className="group cursor-pointer rounded-2xl border border-dashed border-[#b8cbc7] bg-white p-6 transition hover:border-[#39704b] hover:shadow-md"><div className="mb-5 flex h-12 w-12 items-center justify-center rounded-xl bg-[#e8efeb] text-[#39704b]"><ImagePlus /></div><h3 className="text-lg font-bold">Fotografías de modelos</h3><p className="mt-2 text-sm leading-6 text-[#668078]">Selecciona una o varias imágenes desde el dispositivo. Se vinculan por nombre de archivo (marca y modelo) y puedes ajustar manualmente.</p><div className="mt-5 inline-flex rounded-xl bg-[#173c3a] px-4 py-3 text-sm font-bold text-white">Seleccionar imágenes<input type="file" accept="image/*" multiple className="hidden" onChange={(event) => { if (event.target.files) importPhotos(event.target.files); }} /></div></label></div>{excel && <Preview title="Vista previa del Excel" onCancel={() => setExcel(null)} onApply={applyExcel} disabled={!excel.records.length || excel.errors.length > 0}><div className="grid gap-3 text-sm sm:grid-cols-4"><Metric label="Hoja" value={excel.sheet || 'No detectada'} /><Metric label="Fila encabezados" value={String(excel.headerRow)} /><Metric label="Registros válidos" value={String(excel.records.length)} /><Metric label="Campos reconocidos" value={String(excel.recognized.length)} /></div>{excel.errors.map((error) => <div key={error} className="mt-4 rounded-lg bg-[#fff0ee] p-3 text-sm text-[#a44335]">{error}</div>)}<div className="mt-5 overflow-auto rounded-xl border"><table className="w-full min-w-[600px] text-left text-sm"><thead className="bg-[#f4f7f6]"><tr><th className="p-3">Marca</th><th className="p-3">Modelo</th><th className="p-3">Año</th><th className="p-3">Tipo</th><th className="p-3">Motor</th></tr></thead><tbody>{excel.records.slice(0, 8).map((row, index) => <tr key={`${row.brand}-${row.model}-${index}`} className="border-t"><td className="p-3">{row.brand}</td><td className="p-3 font-semibold">{row.model}</td><td className="p-3">{row.year || '—'}</td><td className="p-3">{row.type || '—'}</td><td className="p-3">{row.engine || '—'}</td></tr>)}</tbody></table></div></Preview>}{pdf && (pdf.scanned ? <div className="mt-5 rounded-2xl border border-[#f0d8b0] bg-[#fff8e9] p-6"><div className="flex items-start gap-3"><div className="mt-1 rounded-xl bg-[#f0d8b0] p-2 text-[#9b6d22]"><FileText size={20} /></div><div><h3 className="text-lg font-bold text-[#9b6d22]">PDF sin texto seleccionable</h3><p className="mt-2 max-w-lg text-sm leading-6 text-[#80662c]">Este PDF parece ser un documento escaneado (imagen) y no contiene texto que se pueda extraer automáticamente. No se simularon datos. Si necesitas cargar estos precios, exporta el PDF original como hoja de cálculo o ingresa los valores manualmente.</p><button onClick={() => setPdf(null)} className="mt-5 rounded-xl border border-[#dce7e2] bg-white px-4 py-3 text-sm font-bold">Cerrar</button></div></div></div> : <div className="mt-5 space-y-5">{pdfPlan && <Preview title="Vista previa de la importación" onCancel={() => { setPdf(null); setPdfPlan(null); }} onApply={applyPdf} disabled={!pdfPlan.added.length && !pdfPlan.updated.length && !pdfPlan.review.length && !pdfPlan.unchanged.length}><div className="grid gap-3 text-sm sm:grid-cols-4"><Metric label="Nuevos" value={String(pdfPlan.added.length)} /><Metric label="Precios modificados" value={String(pdfPlan.updated.length)} /><Metric label="Sin cambios" value={String(pdfPlan.unchanged.length)} /><Metric label="En revisión" value={String(pdfPlan.review.length)} /></div>{pdfPlan.manual.length > 0 && <div className="rounded-xl bg-[#fff8e9] p-4 text-sm"><div className="mb-2 font-bold text-[#80662c]">Ajustes manuales detectados — elige qué conservar:</div>{pdfPlan.manual.map(({ vehicle, row }) => <div key={vehicle.id} className="mt-3 flex flex-wrap items-center justify-between gap-3 rounded-lg bg-white p-3"><div className="text-sm"><b>{vehicle.brand} {vehicle.model}</b> — oficial anterior {money(vehicle.officialPrice ?? vehicle.price)} · nuevo oficial {money(row.price)}</div><div className="flex gap-2"><button onClick={() => resolveManual(vehicle, row, true)} className="rounded-lg border border-[#dce7e2] px-3 py-2 text-xs font-bold">Conservar ajuste manual</button><button onClick={() => resolveManual(vehicle, row, false)} className="rounded-lg bg-[#173c3a] px-3 py-2 text-xs font-bold text-white">Usar nuevo oficial</button></div></div>)}</div>}{pdfPlan.added.length > 0 && <Section title={`Vehículos nuevos (${pdfPlan.added.length})`}><div className="max-h-52 overflow-auto rounded-xl border"><table className="w-full min-w-[600px] text-left text-sm"><thead className="sticky top-0 bg-[#f4f7f6]"><tr><th className="p-3">Marca</th><th className="p-3">Modelo</th><th className="p-3">Año</th><th className="p-3">Precio</th><th className="p-3">Condición</th></tr></thead><tbody>{pdfPlan.added.map(({ row }, index) => <tr key={`new-${index}`} className="border-t"><td className="p-3">{row.brand}</td><td className="p-3 font-semibold">{row.model}</td><td className="p-3">{row.year || '—'}</td><td className="p-3">{money(row.price)}</td><td className="p-3 text-xs">{row.priceCondition || '—'}</td></tr>)}</tbody></table></div></Section>}{pdfPlan.updated.length > 0 && <Section title={`Precios oficiales modificados (${pdfPlan.updated.length})`}><div className="max-h-52 overflow-auto rounded-xl border"><table className="w-full min-w-[600px] text-left text-sm"><thead className="sticky top-0 bg-[#f4f7f6]"><tr><th className="p-3">Marca</th><th className="p-3">Modelo</th><th className="p-3">Anterior</th><th className="p-3">Nuevo</th></tr></thead><tbody>{pdfPlan.updated.map(({ vehicle, row }) => <tr key={vehicle.id} className="border-t"><td className="p-3">{vehicle.brand}</td><td className="p-3 font-semibold">{vehicle.model}</td><td className="p-3 text-[#668078]">{money(vehicle.officialPrice ?? vehicle.price)}</td><td className="p-3 font-bold text-[#39704b]">{money(row.price)}</td></tr>)}</tbody></table></div></Section>}{pdfPlan.review.length > 0 && <Section title={`Registros que requieren revisión (${pdfPlan.review.length})`}><div className="max-h-52 overflow-auto rounded-xl border"><table className="w-full min-w-[600px] text-left text-sm"><thead className="sticky top-0 bg-[#f4f7f6]"><tr><th className="p-3">Marca</th><th className="p-3">Modelo</th><th className="p-3">Texto del precio</th><th className="p-3">Condición</th></tr></thead><tbody>{pdfPlan.review.map(({ vehicle, row }, index) => <tr key={`rev-${index}`} className="border-t bg-[#fff8e9]"><td className="p-3">{row.brand}</td><td className="p-3 font-semibold">{row.model}</td><td className="p-3">{row.priceText}</td><td className="p-3 text-xs">{row.priceCondition || 'Precio no interpretado'}</td></tr>)}</tbody></table></div></Section>}{pdfPlan.missing.length > 0 && <Section title={`Vehículos del catálogo no presentes en el PDF (${pdfPlan.missing.length}) — no se eliminan`}><div className="text-sm text-[#668078]">{pdfPlan.missing.slice(0, 8).map((v) => `${v.brand} ${v.model}`).join(' · ')}{pdfPlan.missing.length > 8 ? '…' : ''}</div></Section>}{pdf.conditions.length > 0 && <div className="rounded-xl bg-[#fff8e9] p-4 text-sm text-[#80662c]"><div className="mb-2 font-bold">Condiciones comerciales generales (no se importan como vehículos):</div><ul className="list-disc space-y-1 pl-5">{pdf.conditions.map((condition, index) => <li key={index}>{condition}</li>)}</ul></div>}</Preview>}{!pdfPlan && <Preview title="Vista previa de precios" onCancel={() => setPdf(null)} onApply={() => {}} disabled><div className="text-sm text-[#668078]">Procesando…</div></Preview>}</div>)}{photoPlan && <Preview title="Vista previa de fotografías" onCancel={cancelPhotos} onApply={() => { void applyPhotos(); }} disabled={!photoPlan.items.some((i) => i.vehicleId)}><div className="grid gap-3 text-sm sm:grid-cols-3"><Metric label="Imágenes seleccionadas" value={String(photoPlan.items.length)} /><Metric label="Vinculadas automáticamente" value={String(photoPlan.items.filter((i) => i.matched).length)} /><Metric label="Sin asignar" value={String(photoPlan.items.filter((i) => !i.vehicleId).length)} /></div><div className="mt-5 grid gap-4 sm:grid-cols-2 lg:grid-cols-3">{photoPlan.items.map((item, index) => <div key={index} className="rounded-xl border border-[#dce7e2] p-3"><img src={item.previewUrl} alt="" className="h-28 w-full rounded-lg object-cover" /><div className="mt-2 flex items-center gap-2"><select value={item.vehicleId} onChange={(event) => setPhotoVehicle(index, event.target.value)} className="w-full rounded-lg border border-[#dce7e2] p-2 text-xs"><option value="">Sin asignar</option>{data.vehicles.map((v) => <option key={v.id} value={v.id}>{v.brand} {v.model}{v.year ? ` · ${v.year}` : ''}</option>)}</select>{item.matched && <span className="shrink-0 rounded-full bg-[#edf6e9] px-2 py-1 text-[10px] font-bold text-[#39704b]">auto</span>}</div></div>)}</div>{(() => { const withoutPhoto = data.vehicles.filter((v) => !v.photoId && !photoPlan.items.some((i) => i.vehicleId === v.id)); return withoutPhoto.length > 0 ? <div className="mt-4 rounded-xl bg-[#fff8e9] p-4 text-sm text-[#80662c]"><div className="font-bold">Modelos sin fotografía ({withoutPhoto.length}):</div><div className="mt-1">{withoutPhoto.slice(0, 12).map((v) => `${v.brand} ${v.model}`).join(' · ')}{withoutPhoto.length > 12 ? '…' : ''}</div></div> : null; })()}</Preview>}</div> }
function Section({ title, children }: { title: string; children: React.ReactNode }) { return <div className="rounded-2xl border border-[#dce7e2] bg-white p-5"><h4 className="mb-3 text-sm font-bold text-[#173c3a]">{title}</h4>{children}</div>; }
function ImportCard({ icon: Icon, title, text, accept, onChange }: { icon: typeof FileText; title: string; text: string; accept: string; onChange: (file: File) => void }) { return <label className="group cursor-pointer rounded-2xl border border-dashed border-[#b8cbc7] bg-white p-6 transition hover:border-[#39704b] hover:shadow-md"><div className="mb-5 flex h-12 w-12 items-center justify-center rounded-xl bg-[#e8f2e9] text-[#39704b]"><Icon /></div><h3 className="text-lg font-bold">{title}</h3><p className="mt-2 text-sm leading-6 text-[#668078]">{text}</p><div className="mt-5 inline-flex rounded-xl bg-[#173c3a] px-4 py-3 text-sm font-bold text-white">Seleccionar archivo <input type="file" accept={accept} className="hidden" onChange={(event) => { const file = event.target.files?.[0]; if (file) onChange(file); }} /></div></label>; }
function Preview({ title, children, onCancel, onApply, disabled }: { title: string; children: React.ReactNode; onCancel: () => void; onApply: () => void; disabled: boolean }) { return <div className="mt-5 rounded-2xl border border-[#dce7e2] bg-white p-6"><div className="mb-5 flex items-center justify-between"><h3 className="text-lg font-bold">{title}</h3><button onClick={onCancel} className="rounded-lg p-2 hover:bg-[#f4f7f6]"><X size={18} /></button></div>{children}<div className="mt-6 flex justify-end gap-3"><button onClick={onCancel} className="rounded-xl border border-[#dce7e2] px-4 py-3 text-sm font-bold">Cancelar</button><button onClick={onApply} disabled={disabled} className="rounded-xl bg-[#173c3a] px-4 py-3 text-sm font-bold text-white disabled:opacity-50">Confirmar cambios</button></div></div>; }
function Metric({ label, value }: { label: string; value: string }) { return <div className="rounded-xl bg-[#f4f7f6] p-3"><div className="text-xs text-[#668078]">{label}</div><div className="mt-1 font-bold">{value}</div></div>; }
function FinanceSettings({ data, updateData }: { data: AppData; updateData: (next: AppData, message?: string) => void }) { const [draft, setDraft] = useState(data.finance); const [company, setCompany] = useState<CompanyInfo>(data.company); const save = (next: FinanceConfig) => { setDraft(next); updateData({ ...data, finance: next }, 'Configuración financiera guardada.'); }; const saveCompany = (next: CompanyInfo) => { setCompany(next); updateData({ ...data, company: next }, 'Datos de empresa guardados.'); }; return <FinanceForm config={draft} setConfig={(next) => setDraft(next)} onSave={save} company={company} onSaveCompany={saveCompany} />; }
function FinanceForm({ config, setConfig, onSave, company, onSaveCompany }: { config: FinanceConfig; setConfig: (config: FinanceConfig) => void; onSave: (config: FinanceConfig) => void; company: CompanyInfo; onSaveCompany: (company: CompanyInfo) => void }) { const update = <K extends keyof FinanceConfig>(key: K, value: FinanceConfig[K]) => { const next = { ...config, [key]: value }; setConfig(next); onSave(next); }; const updateCompany = <K extends keyof CompanyInfo>(key: K, value: CompanyInfo[K]) => { const next = { ...company, [key]: value }; onSaveCompany(next); }; return <div className="fade-in"><div className="mb-6"><p className="text-sm text-[#668078]">Valores usados por defecto en futuras cotizaciones</p><h2 className="mt-1 text-3xl font-bold">Configuración financiera</h2></div><div className="rounded-2xl border border-[#dce7e2] bg-white p-6"><div className="mb-5 rounded-xl bg-[#f4f7f6] p-4"><div className="text-sm font-bold text-[#173c3a]">Datos de empresa y asesor</div><div className="mt-4 grid gap-4 md:grid-cols-2"><Field label="Nombre de empresa"><input value={company.name} onChange={(event) => updateCompany('name', event.target.value)} className="field" placeholder="SAMADI Ecuador" /></Field><Field label="Nombre del asesor"><input value={company.advisorName} onChange={(event) => updateCompany('advisorName', event.target.value)} className="field" placeholder="Jorge" /></Field></div></div><div className="grid gap-5 md:grid-cols-2"><Field label="Tasa de interés (%)"><input type="number" step="0.01" value={config.annualRate} onChange={(event) => update('annualRate', Number(event.target.value))} className="field" /></Field><Field label="Periodicidad"><select value={config.ratePeriod} onChange={(event) => update('ratePeriod', event.target.value as FinanceConfig['ratePeriod'])} className="field"><option>Anual</option><option>Mensual</option></select></Field><Field label="Entrada predeterminada (%)"><input type="number" min="0" max="100" value={config.entryPercent} onChange={(event) => update('entryPercent', Number(event.target.value))} className="field" /></Field><Field label="Plazo predeterminado (meses)"><select value={config.term} onChange={(event) => update('term', Number(event.target.value))} className="field">{config.enabledTerms.map((term) => <option key={term}>{term}</option>)}</select></Field><Field label="Seguro de desgravamen"><div className="flex gap-2"><select value={config.insuranceMode} onChange={(event) => update('insuranceMode', event.target.value as FinanceConfig['insuranceMode'])} className="field"><option>Porcentaje</option><option>Valor fijo</option></select><input type="number" step="0.01" value={config.insuranceValue} onChange={(event) => update('insuranceValue', Number(event.target.value))} className="field" /></div></Field><Field label="Seguro: aplicación"><select value={config.insuranceApplication} onChange={(event) => update('insuranceApplication', event.target.value as FinanceConfig['insuranceApplication'])} className="field"><option>Por cuota</option><option>Capitalizado</option><option>Único</option></select></Field><Field label="Impuestos y tributos"><div className="flex gap-2"><select value={config.taxMode} onChange={(event) => update('taxMode', event.target.value as FinanceConfig['taxMode'])} className="field"><option>Porcentaje</option><option>Valor fijo</option></select><input type="number" step="0.01" value={config.taxValue} onChange={(event) => update('taxValue', Number(event.target.value))} className="field" /></div></Field><Field label="Impuestos: base"><select value={config.taxBase} onChange={(event) => update('taxBase', event.target.value as FinanceConfig['taxBase'])} className="field"><option>Precio</option><option>Monto financiado</option></select></Field></div><div className="mt-6 rounded-xl bg-[#e8f2e9] p-4 text-sm leading-6 text-[#39704b]"><Check className="mr-2 inline" size={16} />Cada cambio se guarda automáticamente para las próximas cotizaciones. Las cotizaciones anteriores conservan sus propios valores.</div><label className="mt-6 block text-sm font-semibold">Notas de fuente<textarea value={config.notes} onChange={(event) => update('notes', event.target.value)} className="field min-h-24" /></label></div></div> }
function Field({ label, children }: { label: string; children: React.ReactNode }) { return <label className="text-sm font-semibold">{label}<div className="mt-2">{children}</div></label>; }
function Backups({ data, updateData }: { data: AppData; updateData: (next: AppData, message?: string) => void }) { const [manifest, setManifest] = useState<BackupManifest | null>(null); const [backupData, setBackupData] = useState<AppData | null>(null); const [error, setError] = useState(''); const [busy, setBusy] = useState(false); const [backupFile, setBackupFile] = useState<File | null>(null); const restore = async (file: File) => { setBusy(true); setError(''); try { const inspected = await inspectBackup(file); setManifest(inspected.manifest); setBackupData(inspected.data); setBackupFile(file); } catch (caught) { setManifest(null); setBackupData(null); setError(caught instanceof Error ? caught.message : 'No se pudo validar el respaldo.'); } finally { setBusy(false); } }; const confirmRestore = async () => { if (!backupData || !manifest) return; if (!window.confirm(`Se reemplazarán los datos actuales por ${manifest.counts.vehicles} vehículos, ${manifest.counts.clients} clientes y ${manifest.counts.quotes} cotizaciones. ¿Deseas continuar?`)) return; setBusy(true); setError(''); try { await downloadBackup(data); let photosRestored = 0; if (backupFile) { try { photosRestored = await restorePhotos(backupFile); } catch { /* respaldo sin fotos o incompatible: continúa sin eliminar fotos existentes */ } } updateData(backupData, `Se creó un respaldo de seguridad y luego se restauraron los datos${photosRestored ? ` con ${photosRestored} fotografías` : ''}.`); setManifest(null); setBackupData(null); setBackupFile(null); } catch { setError('No se pudo crear el respaldo de seguridad. La restauración fue cancelada y los datos actuales se conservaron.'); } finally { setBusy(false); } }; return <div className="fade-in"><div className="mb-6"><p className="text-sm text-[#668078]">Copia integral del trabajo local</p><h2 className="mt-1 text-3xl font-bold">Respaldos y exportaciones</h2></div><div className="grid gap-5 lg:grid-cols-2"><div className="rounded-2xl border border-[#dce7e2] bg-white p-6"><div className="mb-5 flex h-12 w-12 items-center justify-center rounded-xl bg-[#e8f2e9] text-[#39704b]"><RefreshCw /></div><h3 className="text-lg font-bold">Crear respaldo completo</h3><p className="mt-2 text-sm leading-6 text-[#668078]">Incluye catálogo, clientes, cotizaciones, configuración financiera y un manifiesto con cantidades y fecha.</p><button onClick={() => { void downloadBackup(data); }} className="mt-5 rounded-xl bg-[#173c3a] px-4 py-3 text-sm font-bold text-white">Descargar respaldo ZIP</button></div><div className="rounded-2xl border border-[#dce7e2] bg-white p-6"><div className="mb-5 flex h-12 w-12 items-center justify-center rounded-xl bg-[#fff1d8] text-[#9b6d22]"><FileText /></div><h3 className="text-lg font-bold">Restaurar respaldo</h3><p className="mt-2 text-sm leading-6 text-[#668078]">Primero se valida el manifiesto y se muestra el contenido. Los datos actuales no cambian hasta confirmar.</p><label className="mt-5 inline-flex cursor-pointer rounded-xl border border-[#dce7e2] px-4 py-3 text-sm font-bold hover:bg-[#f4f7f6]">{busy ? 'Validando…' : 'Seleccionar archivo ZIP'}<input type="file" accept=".zip" className="hidden" onChange={(event) => { const file = event.target.files?.[0]; if (file) void restore(file); }} /></label>{error && <div className="mt-4 rounded-xl bg-[#fff0ee] p-3 text-sm text-[#a44335]">{error}</div>}</div></div><div className="mt-5 rounded-2xl border border-[#dce7e2] bg-white p-6"><h3 className="text-lg font-bold">Exportar datos para compartir</h3><p className="mt-2 text-sm text-[#668078]">Estas copias son hojas de trabajo y no sustituyen el respaldo ZIP completo.</p><div className="mt-5 flex flex-wrap gap-3"><button onClick={() => downloadCsv(data, 'vehicles')} className="rounded-xl border border-[#dce7e2] px-4 py-3 text-sm font-bold">Catálogo CSV</button><button onClick={() => downloadCsv(data, 'clients')} className="rounded-xl border border-[#dce7e2] px-4 py-3 text-sm font-bold">Clientes CSV</button><button onClick={() => downloadCsv(data, 'quotes')} className="rounded-xl border border-[#dce7e2] px-4 py-3 text-sm font-bold">Cotizaciones CSV</button></div></div>{manifest && backupData && <div className="mt-5 rounded-2xl border border-[#b8cbc7] bg-[#eff9ed] p-6"><div className="flex items-start justify-between gap-4"><div><h3 className="text-lg font-bold text-[#173c3a]">Respaldo validado</h3><p className="mt-1 text-sm text-[#39704b]">Creado el {new Date(manifest.createdAt).toLocaleString('es-EC')} · versión {manifest.version}</p></div><Check className="text-[#39704b]" /></div><div className="mt-5 grid gap-3 sm:grid-cols-3"><Metric label="Vehículos" value={String(manifest.counts.vehicles)} /><Metric label="Clientes" value={String(manifest.counts.clients)} /><Metric label="Cotizaciones" value={String(manifest.counts.quotes)} /></div><button onClick={confirmRestore} className="mt-5 rounded-xl bg-[#173c3a] px-4 py-3 text-sm font-bold text-white">Confirmar restauración</button></div>}</div> }
function EmptyState({ title, text, button, onClick }: { title: string; text: string; button?: string; onClick?: () => void }) { return <div className="rounded-2xl border border-dashed border-[#b8cbc7] bg-white p-10 text-center"><div className="text-lg font-bold">{title}</div><p className="mx-auto mt-2 max-w-md text-sm leading-6 text-[#668078]">{text}</p>{button && onClick && <button onClick={onClick} className="mt-5 rounded-xl bg-[#173c3a] px-4 py-3 text-sm font-bold text-white">{button}</button>}</div>; }

export default App;
